async function promisePopupClosed(tagsPopup) {
  const parentPopup = tagsPopup.parentNode.closest("menupopup");
  if (tagsPopup.state == "open") {
    tagsPopup.hidePopup();
  }
  await BrowserTestUtils.waitForPopupEvent(tagsPopup, "hidden");
  if (parentPopup) {
    if (parentPopup.state == "open") {
      parentPopup.hidePopup();
    }
    await BrowserTestUtils.waitForPopupEvent(parentPopup, "hidden");
  }
  await SimpleTest.promiseFocus(tagsPopup.documentGlobal.top);
  await TestUtils.waitForTick();
}
